// PHARMACOLOGY — Katzung, Lippincott
// ============================================================
const pharmacologyMCQs = [
  // --- PHARMACOKINETICS ---
  { id: 'pha_1', text: 'The half-life of a drug is the time required to:', options: ['Eliminate 100% of the drug', 'Reduce drug concentration by 50%', 'Achieve peak plasma concentration', 'Reach steady-state concentration'], correct: 1, explanation: 'Half-life (t½) is the time for drug concentration to decrease by 50%. It determines dosing interval and time to steady state (4-5 half-lives). t½ = 0.693 × Vd / CL.', difficulty: 'easy' },
  { id: 'pha_2', text: 'First-pass metabolism is most relevant for drugs given by which route?', options: ['IV injection', 'Sublingual', 'Oral route', 'Transdermal'], correct: 2, explanation: 'First-pass metabolism occurs when orally absorbed drugs pass through the portal circulation and are metabolized by the liver before reaching systemic circulation, greatly reducing bioavailability.', difficulty: 'easy' },
  { id: 'pha_3', text: 'A drug with a narrow therapeutic index requires careful monitoring because:', options: ['It has a very long half-life', 'The toxic dose is close to the therapeutic dose', 'It is rapidly eliminated', 'It has high protein binding'], correct: 1, explanation: 'Narrow therapeutic index (e.g., digoxin, warfarin, lithium, phenytoin) means the difference between effective dose and toxic dose is small, requiring close monitoring of drug levels.', difficulty: 'medium' },
  { id: 'pha_4', text: 'Phase II drug metabolism primarily involves:', options: ['Oxidation by CYP450 enzymes', 'Conjugation reactions (glucuronidation, sulfation, acetylation)', 'Hydrolysis of ester bonds', 'Reduction reactions'], correct: 1, explanation: 'Phase II reactions are synthetic (conjugation) reactions: glucuronidation, sulfation, acetylation, methylation, and glutathione conjugation. They generally increase water solubility for renal excretion.', difficulty: 'medium' },

  // --- AUTONOMIC ---
  { id: 'pha_5', text: 'Atropine blocks which type of receptor?', options: ['Nicotinic acetylcholine receptors', 'Muscarinic acetylcholine receptors', 'Alpha-adrenergic receptors', 'Beta-adrenergic receptors'], correct: 1, explanation: 'Atropine is a competitive muscarinic receptor antagonist. It blocks M1-M5 receptors causing: dry mouth, mydriasis, tachycardia, urinary retention, decreased GI motility, dry skin.', difficulty: 'easy' },
  { id: 'pha_6', text: 'Propranolol is a non-selective beta-blocker. Which side effect is most dangerous in asthmatics?', options: ['Bradycardia', 'Hypoglycemia masking', 'Bronchoconstriction via β2 blockade', 'Fatigue'], correct: 2, explanation: 'Non-selective beta-blockers block β2 receptors in bronchial smooth muscle, causing bronchoconstriction. This is dangerous in asthmatics. Cardioselective beta-blockers (metoprolol, atenolol) are safer.', difficulty: 'medium' },
  { id: 'pha_7', text: 'Phenylephrine is used as a nasal decongestant because it:', options: ['Blocks α1-adrenergic receptors', 'Stimulates β2 receptors', 'Stimulates α1-adrenergic receptors causing vasoconstriction', 'Inhibits histamine release'], correct: 2, explanation: 'Phenylephrine is a selective α1 agonist that causes vasoconstriction of nasal mucosal blood vessels, reducing congestion and edema. Unlike pseudoephedrine, it doesn\'t have CNS stimulant effects.', difficulty: 'medium' },

  // --- CARDIOVASCULAR ---
  { id: 'pha_8', text: 'The mechanism of action of ACE inhibitors (e.g., Enalapril) is:', options: ['Block angiotensin II AT1 receptors', 'Inhibit conversion of Angiotensin I to Angiotensin II by ACE', 'Block aldosterone receptors', 'Inhibit renin release'], correct: 1, explanation: 'ACE inhibitors block angiotensin-converting enzyme (ACE/kininase II), preventing conversion of Ang I → Ang II, and also preventing bradykinin breakdown. Result: vasodilation, reduced aldosterone, reduced preload/afterload.', difficulty: 'easy' },
  { id: 'pha_9', text: 'A patient on heparin develops HIT (Heparin-Induced Thrombocytopenia). The safest alternative anticoagulant is:', options: ['Warfarin (immediately)', 'Low molecular weight heparin', 'Argatroban (direct thrombin inhibitor)', 'Aspirin'], correct: 2, explanation: 'In HIT, heparin must be stopped immediately. Warfarin is contraindicated initially (risk of limb gangrene). Argatroban or bivalirudin (direct thrombin inhibitors) are safe alternatives as they don\'t cross-react with HIT antibodies.', difficulty: 'hard' },
  { id: 'pha_10', text: 'Digoxin toxicity causes which characteristic arrhythmia?', options: ['AV block with junctional escape rhythm', 'Supraventricular tachycardia', 'Broad complex QRS without arrhythmia', 'Sinus tachycardia'], correct: 0, explanation: 'Digoxin toxicity characteristically causes PAT with block (paroxysmal atrial tachycardia with AV block) — the combination of increased automaticity (AV junctional escape) and AV block is pathognomonic.', difficulty: 'hard' },

  // --- ANTIMICROBIALS ---
  { id: 'pha_11', text: 'Beta-lactam antibiotics kill bacteria by:', options: ['Inhibiting 50S ribosomal subunit', 'Disrupting cell membrane integrity', 'Inhibiting transpeptidation (cross-linking) of peptidoglycan cell wall', 'Inhibiting DNA gyrase'], correct: 2, explanation: 'Beta-lactams (penicillins, cephalosporins, carbapenems) inhibit transpeptidases (Penicillin-Binding Proteins, PBPs), preventing cross-linking of peptidoglycan. This weakens the cell wall, causing osmotic lysis.', difficulty: 'medium' },
  { id: 'pha_12', text: 'Aminoglycosides (e.g., Gentamicin) cause nephrotoxicity because they:', options: ['Are freely filtered but not reabsorbed', 'Accumulate in proximal tubular cells and cause direct cytotoxicity', 'Cause intense renal vasoconstriction', 'Block renal ADH receptors'], correct: 1, explanation: 'Aminoglycosides are concentrated in proximal tubular cells (via cation transport), causing mitochondrial damage and cell death (acute tubular necrosis). Risk increases with duration of therapy and concurrent nephrotoxins.', difficulty: 'hard' },
  { id: 'pha_13', text: 'A patient develops tendon rupture after taking an antibiotic for UTI. Which drug is responsible?', options: ['Amoxicillin', 'Trimethoprim-sulfamethoxazole', 'Fluoroquinolone (e.g., Ciprofloxacin)', 'Nitrofurantoin'], correct: 2, explanation: 'Fluoroquinolones (ciprofloxacin, levofloxacin) are associated with tendinopathy and tendon rupture (especially Achilles tendon), arthropathy, peripheral neuropathy, and QT prolongation. Contraindicated in children/pregnancy.', difficulty: 'medium' },

  // --- CNS DRUGS ---
  { id: 'pha_14', text: 'The mechanism of action of benzodiazepines is:', options: ['Block NMDA glutamate receptors', 'Potentiate GABA-A receptor by increasing frequency of Cl- channel opening', 'Block serotonin reuptake', 'Inhibit MAO enzymes'], correct: 1, explanation: 'Benzodiazepines bind to the GABA-A receptor at a site distinct from GABA, increasing the frequency of Cl- channel opening when GABA is present. This enhances inhibitory neurotransmission (anxiolytic, sedative, anticonvulsant).', difficulty: 'medium' },
  { id: 'pha_15', text: 'Serotonin syndrome is caused by excess serotonergic activity and can occur with:', options: ['SSRI + MAOI combination', 'SSRI + beta-blocker', 'Tricyclic + aspirin', 'Lithium + haloperidol'], correct: 0, explanation: 'Serotonin syndrome occurs with combinations increasing serotonin: SSRI+MAOI, SSRI+tramadol, SSRI+linezolid. Features: hyperthermia, agitation, clonus, tremor, mydriasis. It\'s a medical emergency.', difficulty: 'hard' },
];

// ============================================================
// MEDICINE — Davidson, Kumar & Clark
