const medicineMCQs = [
  { id: 'med_1', text: 'The most sensitive initial test for suspected myocardial infarction is:', options: ['ECG (ST elevation)', 'CK-MB', 'Troponin I or T', 'Myoglobin'], correct: 2, explanation: 'Troponin I and T are the most sensitive and specific biomarkers for myocardial injury. They rise within 4-6 hours and remain elevated for 10-14 days, useful for late diagnosis.', difficulty: 'medium' },
  { id: 'med_2', text: 'A patient has BP 160/100 on 3 occasions. Investigations show: K+ 2.8, HCO3- 28, normal aldosterone:renin ratio. Most likely diagnosis:', options: ['Primary hyperaldosteronism (Conn\'s syndrome)', 'Cushing\'s syndrome', 'Renovascular hypertension', 'Essential hypertension with diuretic use'], correct: 0, explanation: 'Conn\'s syndrome (primary hyperaldosteronism): hypertension + hypokalemia + metabolic alkalosis with elevated aldosterone and suppressed renin (low aldosterone:renin ratio actually means high ratio). Most common cause: adrenal adenoma.', difficulty: 'hard' },
  { id: 'med_3', text: 'A 55-year-old smoker presents with progressive dyspnea, barrel chest, and decreased breath sounds. FEV1/FVC = 58%. Most likely diagnosis:', options: ['Asthma', 'Pulmonary fibrosis', 'COPD (Emphysema)', 'Pulmonary embolism'], correct: 2, explanation: 'COPD: history of smoking + progressive dyspnea + barrel chest (hyperinflation) + obstructive spirometry (FEV1/FVC < 70%). Emphysema causes decreased breath sounds due to air trapping and hyperinflated lungs.', difficulty: 'medium' },
  { id: 'med_4', text: 'The CURB-65 score for community-acquired pneumonia severity includes all of the following EXCEPT:', options: ['Confusion', 'Urea > 7 mmol/L', 'Respiratory rate ≥ 30/min', 'Oxygen saturation < 90%'], correct: 3, explanation: 'CURB-65: Confusion, Urea > 7 mmol/L, RR ≥ 30/min, Blood pressure < 90 systolic or ≤ 60 diastolic, Age ≥ 65. O2 saturation is NOT part of CURB-65 (it is in PSI/PORT score).', difficulty: 'hard' },
  { id: 'med_5', text: 'Which of the following is the FIRST-LINE treatment for Helicobacter pylori eradication?', options: ['Omeprazole alone', 'Triple therapy: PPI + Clarithromycin + Amoxicillin for 7-14 days', 'Metronidazole alone', 'H2-blocker + Bismuth'], correct: 1, explanation: 'Standard triple therapy (PPI + clarithromycin + amoxicillin or metronidazole) for 7-14 days is first-line for H. pylori eradication. "Test and treat" is the preferred strategy before endoscopy in young patients.', difficulty: 'medium' },
  { id: 'med_6', text: 'Type 1 Diabetes Mellitus differs from Type 2 primarily in that:', options: ['Type 1 is more common in obese adults', 'Type 1 is managed with diet alone initially', 'Type 1 has absolute insulin deficiency due to autoimmune beta-cell destruction', 'Type 2 always requires insulin from onset'], correct: 2, explanation: 'T1DM: autoimmune destruction of pancreatic beta cells → absolute insulin deficiency → ketoacidosis-prone. T2DM: insulin resistance + relative insulin deficiency; managed initially with lifestyle and oral agents.', difficulty: 'easy' },
  { id: 'med_7', text: 'A patient presents with jaundice, dark urine, pale stools, and pruritus. Bilirubin is predominantly conjugated. This pattern suggests:', options: ['Hemolytic jaundice', 'Gilbert\'s syndrome', 'Obstructive (cholestatic) jaundice', 'Hepatocellular jaundice'], correct: 2, explanation: 'Obstructive/cholestatic jaundice: predominantly conjugated (direct) hyperbilirubinemia + dark urine (bilirubinuria) + pale stools (absent urobilinogen) + pruritus (bile salt deposition). Causes: choledocholithiasis, cholangiocarcinoma, pancreatic head cancer.', difficulty: 'medium' },
  { id: 'med_8', text: 'Which anti-epileptic drug is CONTRAINDICATED in absence seizures?', options: ['Ethosuximide', 'Valproate', 'Lamotrigine', 'Carbamazepine'], correct: 3, explanation: 'Carbamazepine (and phenytoin) can worsen absence and myoclonic seizures. First-line for absence seizures is ethosuximide or valproate.', difficulty: 'hard' },
  { id: 'med_9', text: 'A patient presents with periorbital edema, proteinuria > 3.5 g/day, hypoalbuminemia, and hyperlipidemia. This is:', options: ['Nephritic syndrome', 'Nephrotic syndrome', 'Acute tubular necrosis', 'Rapidly progressive glomerulonephritis'], correct: 1, explanation: 'Nephrotic syndrome triad: massive proteinuria (>3.5g/day) + hypoalbuminemia + edema + hyperlipidemia + lipiduria. No hematuria/hypertension (unlike nephritic). Most common cause in adults: membranous nephropathy.', difficulty: 'easy' },
  { id: 'med_10', text: 'The classic triad of Cushing\'s syndrome includes:', options: ['Hypotension, weight loss, hyperpigmentation', 'Moon face, central obesity, purple striae', 'Exophthalmos, tremor, heat intolerance', 'Hypocalcemia, tetany, cataracts'], correct: 1, explanation: 'Cushing\'s syndrome (hypercortisolism): moon face, buffalo hump, central obesity, purple abdominal striae, hypertension, hyperglycemia, hirsutism, osteoporosis, and easy bruising.', difficulty: 'easy' },
];

