const surgeryMCQs = [
  { id: 'sur_1', text: 'The most common site for carcinoma of the colon is the:', options: ['Ascending colon', 'Transverse colon', 'Descending colon', 'Rectosigmoid junction'], correct: 3, explanation: 'Rectosigmoid junction is the most common site for colorectal carcinoma. Left-sided tumors present with change in bowel habits and obstruction; right-sided present with occult bleeding and anemia.', difficulty: 'medium' },
  { id: 'sur_2', text: 'The diagnostic test of choice for acute appendicitis in a pregnant woman is:', options: ['CT scan abdomen', 'Plain X-ray', 'MRI abdomen', 'Alvarado score clinical diagnosis only'], correct: 2, explanation: 'MRI is the preferred imaging for acute appendicitis in pregnancy (no ionizing radiation risk to fetus). CT is accurate but carries radiation risk. Ultrasound is first-line but limited in pregnancy.', difficulty: 'hard' },
  { id: 'sur_3', text: 'A 45-year-old presents with painless obstructive jaundice, weight loss, and a palpable gallbladder. This is called:', options: ['Charcot\'s triad', 'Courvoisier\'s law', 'Reynolds pentad', 'Murphy\'s sign'], correct: 1, explanation: 'Courvoisier\'s law: a palpable, non-tender gallbladder in the presence of jaundice is unlikely to be due to gallstones (chronic inflammation causes fibrosis). It suggests malignant obstruction (commonly pancreatic head carcinoma).', difficulty: 'medium' },
  { id: 'sur_4', text: 'The most important prognostic factor in breast cancer is:', options: ['Tumor size', 'Lymph node status', 'Histological grade', 'ER/PR receptor status'], correct: 1, explanation: 'Axillary lymph node status (number of involved nodes) is the single most important prognostic factor in breast cancer. Sentinel lymph node biopsy is now standard for clinically node-negative disease.', difficulty: 'medium' },
  { id: 'sur_5', text: 'Virchow\'s triad (risk factors for DVT) consists of:', options: ['Inflammation, infection, immune activation', 'Stasis, endothelial injury, hypercoagulability', 'Obesity, hypertension, diabetes', 'Age, sex, family history'], correct: 1, explanation: 'Virchow\'s triad: (1) venous stasis (immobility, CHF), (2) endothelial injury (trauma, surgery), (3) hypercoagulability (thrombophilia, malignancy, oral contraceptives). All promote DVT formation.', difficulty: 'easy' },
  { id: 'sur_6', text: 'The definitive treatment of choice for perforated duodenal ulcer is:', options: ['Conservative management with IV antibiotics', 'Graham\'s patch repair (omental patch)', 'Gastrectomy', 'Highly selective vagotomy'], correct: 1, explanation: 'Graham\'s omental patch repair is the procedure of choice for perforated duodenal ulcer. The omentum is sutured over the perforation. Definitive anti-ulcer surgery is now rarely needed with effective H. pylori eradication.', difficulty: 'medium' },
  { id: 'sur_7', text: 'In primary survey (ATLS protocol), airway management takes priority. After establishing airway, the next priority is:', options: ['Disability (neurological assessment)', 'Circulation with hemorrhage control', 'Breathing and ventilation', 'Exposure and environment'], correct: 2, explanation: 'ATLS primary survey: A - Airway (with C-spine control), B - Breathing/ventilation, C - Circulation/hemorrhage, D - Disability, E - Exposure. Airway → Breathing → Circulation sequence.', difficulty: 'medium' },
  { id: 'sur_8', text: 'A patient with a stab wound to the chest develops hypotension, distended neck veins, and muffled heart sounds. This triad is called:', options: ['Virchow\'s triad', 'Beck\'s triad (cardiac tamponade)', 'Charcot\'s triad', 'Cushing\'s triad'], correct: 1, explanation: 'Beck\'s triad of cardiac tamponade: (1) hypotension, (2) distended neck veins (JVD), (3) muffled heart sounds. Pulsus paradoxus (>10 mmHg BP drop on inspiration) is also a key sign. Treatment: pericardiocentesis.', difficulty: 'easy' },
  { id: 'sur_9', text: 'What percentage of body surface area (BSA) is attributed to the entire head and neck in the Rule of Nines in adults?', options: ['4.5%', '9%', '18%', '1%'], correct: 1, explanation: 'Rule of Nines (adults): Head and neck = 9%, each upper limb = 9%, chest = 18%, abdomen = 18%, each lower limb = 18%, perineum = 1%. Total = 100%.', difficulty: 'easy' },
  { id: 'sur_10', text: 'The most common type of hernia in females is:', options: ['Inguinal hernia', 'Femoral hernia', 'Umbilical hernia', 'Incisional hernia'], correct: 1, explanation: 'Femoral hernia is more common in females (due to wider female pelvis), though inguinal hernia is more common overall. Femoral hernias have a higher risk of strangulation and require urgent repair.', difficulty: 'medium' },
];

